import{_ as t,o,c as r,a5 as a}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"Vue 响应式数据原理","description":"Vue 3.x 响应式数据原理 Vue 3 引入了全新的响应式系统，它是基于 Proxy API 实现的，较 Vue 2 的 Object.defineProperty 方式有了很大的提升。下面详细介绍 Vue 3 的响应式数据原理，并对比 Vue 2 的实现方式。 Vue 3。","frontmatter":{"title":"Vue 响应式数据原理","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","原理与手写实现"],"description":"Vue 3.x 响应式数据原理 Vue 3 引入了全新的响应式系统，它是基于 Proxy API 实现的，较 Vue 2 的 Object.defineProperty 方式有了很大的提升。下面详细介绍 Vue 3 的响应式数据原理，并对比 Vue 2 的实现方式。 Vue 3。","sidebarWeight":13,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/原理/Vue 响应式数据原理.md"},"headers":[],"relativePath":"posts/Vue系统教程/05-原理与手写实现/Vue 响应式数据原理.md","filePath":"posts/Vue系统教程/05-原理与手写实现/Vue 响应式数据原理.md"}'),d={name:"posts/Vue系统教程/05-原理与手写实现/Vue 响应式数据原理.md"};function u(s,e,n,c,i,l){return o(),r("div",null,[...e[0]||(e[0]=[a('<div><h1 id="vue-响应式数据原理" tabindex="-1">Vue 响应式数据原理 <a class="header-anchor" href="#vue-响应式数据原理" aria-label="Permalink to &quot;Vue 响应式数据原理&quot;">​</a></h1><blockquote><p>本节目标：理解“Vue 响应式数据原理”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><h3 id="vue-3-x-响应式数据原理" tabindex="-1">Vue 3.x 响应式数据原理 <a class="header-anchor" href="#vue-3-x-响应式数据原理" aria-label="Permalink to &quot;Vue 3.x 响应式数据原理&quot;">​</a></h3><p>Vue 3 引入了全新的响应式系统，它是基于 Proxy API 实现的，较 Vue 2 的 Object.defineProperty 方式有了很大的提升。下面详细介绍 Vue 3 的响应式数据原理，并对比 Vue 2 的实现方式。</p><h4 id="vue-3-响应式数据原理" tabindex="-1">Vue 3 响应式数据原理 <a class="header-anchor" href="#vue-3-响应式数据原理" aria-label="Permalink to &quot;Vue 3 响应式数据原理&quot;">​</a></h4><ol><li><strong>Proxy</strong>：Vue 3 使用 Proxy 来实现响应式代理。Proxy 可以直接拦截对对象的所有操作，使得 Vue 3 可以轻松监听对象的变化。</li><li><strong>Reactive API</strong>：Vue 3 提供了 <code>reactive</code> 和 <code>ref</code> 这两个 API 来创建响应式对象。</li></ol><ul><li><code>reactive</code>：用于将一个普通对象转换为响应式对象。</li><li><code>ref</code>：用于创建一个持有单个值的响应式对象。</li></ul><ol start="3"><li><strong>响应式追踪与更新</strong>：当你访问响应式对象的属性时，Proxy 会通过 <code>get</code> 拦截器进行依赖收集；当你修改属性时，Proxy 会通过 <code>set</code> 拦截器进行依赖触发，更新相关的视图。 import { reactive, ref, effect } from &#39;vue&#39;; const state = reactive({ count: 0 }); const count = ref(0); effect(() =&gt; { console.log(state.count); // 依赖收集 console.log(count.value); // 依赖收集 }); state.count++; // 触发依赖更新 count.value++; // 触发依赖更新</li></ol><h4 id="vue-2-响应式数据原理" tabindex="-1">Vue 2 响应式数据原理 <a class="header-anchor" href="#vue-2-响应式数据原理" aria-label="Permalink to &quot;Vue 2 响应式数据原理&quot;">​</a></h4><ol><li><strong>Object.defineProperty</strong>：Vue 2 使用 <code>Object.defineProperty</code> 为对象的每个属性添加 getter 和 setter，从而实现对属性的监听。这种方式有一些局限性，比如无法监听数组的索引变化和新属性的添加。</li><li><strong>依赖收集与派发更新</strong>：Vue 2 在对象的 getter 中进行依赖收集，在 setter 中派发更新。每个响应式对象都有一个 Dep 实例，存储依赖它的 Watcher。 function defineReactive(obj, key, val) { const dep = new Dep(); Object.defineProperty(obj, key, { get() { dep.depend(); return val; }, set(newVal) { val = newVal; dep.notify(); } }); } class Dep { constructor() { this.subs = []; } depend() { if (Dep.target) { this.subs.push(Dep.target); } } notify() { this.subs.forEach(sub =&gt; sub.update()); } } class Watcher { constructor(fn) { Dep.target = this; this.fn = fn; this.fn(); Dep.target = null; } update() { this.fn(); } } const state = { count: 0 }; defineReactive(state, &#39;count&#39;, state.count); new Watcher(() =&gt; { console.log(state.count); // 依赖收集 }); state.count++; // 触发依赖更新</li></ol><p>Vue 3 和 Vue 2 对比</p><table tabindex="0"><thead><tr><th></th><th></th><th></th></tr></thead><tbody><tr><td><strong>特性</strong></td><td><strong>Vue 2</strong></td><td><strong>Vue 3</strong></td></tr><tr><td>响应式实现方式</td><td>Object.defineProperty</td><td>Proxy</td></tr><tr><td>依赖收集与更新</td><td>在 getter 和 setter 中手动实现</td><td>Proxy 自动拦截对象的所有操作</td></tr><tr><td>数组和新增属性的监听</td><td>需要额外的处理，如 Vue.set</td><td>Proxy 能直接监听数组和新增属性的变化</td></tr><tr><td>性能和灵活性</td><td>性能相对较低，灵活性受限</td><td>性能更高，更加灵活</td></tr><tr><td>API</td><td>Vue 实例化时创建响应式对象</td><td>reactive 和 ref API 创建响应式对象</td></tr></tbody></table><p>总结 Vue 3 通过使用 Proxy 进行响应式数据的实现，使得性能和灵活性得到了大幅提升。同时提供了 <code>reactive</code> 和 <code>ref</code> API，更加直观和方便地创建响应式对象。相较于 Vue 2，Vue 3 的响应式系统更加现代化和高效。</p></div>',1)])])}const f=t(d,[["render",u]]);export{p as __pageData,f as default};
